import{_ as e,o as a,c as s,a3 as d}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Modelos de mensagem","description":"","frontmatter":{"title":"Modelos de mensagem","id":"eproc-modelos-mensagem","plataforma":"eproc","grupo":"E-mail","plano":"free","desde":"1.0.10","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-modelos-mensagem"}]]},"headers":[],"relativePath":"funcionalidades/eproc-modelos-mensagem.md","filePath":"funcionalidades/eproc-modelos-mensagem.md"}'),t={name:"funcionalidades/eproc-modelos-mensagem.md"};function r(i,o,l,n,m,c){return a(),s("div",null,o[0]||(o[0]=[d('<h1 id="modelos-de-mensagem" tabindex="-1">Modelos de mensagem <a class="header-anchor" href="#modelos-de-mensagem" aria-label="Permalink to &quot;Modelos de mensagem&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Permite salvar textos padrão e inseri-los no campo &quot;Mensagem&quot; do envio de e-mail com um clique. Cada modelo pode trazer também um assunto e usar variáveis, como o número do processo e o nome do autor, preenchidas com os dados do processo.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, tela de envio de e-mail do processo, num seletor entre &quot;Assunto&quot; e &quot;Mensagem&quot;. Os modelos são cadastrados nas configurações do eploc (&quot;Gerenciar modelos de mensagem&quot;), também acessíveis pelo popup.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><p><strong>Cadastrar um modelo</strong></p><ol><li>Nas configurações do eploc, no card do recurso, clique em <strong>Gerenciar modelos de mensagem</strong>.</li><li>Clique em <strong>Novo</strong>, preencha o nome do modelo, o assunto (opcional) e o texto.</li><li>Para usar dados do processo, clique numa das variáveis listadas ou digite-a entre arrobas, como <code>@numerodoprocesso@</code>.</li><li>Clique em <strong>Salvar modelo</strong>. Marque a estrela de um modelo para torná-lo o padrão.</li></ol><p><strong>Usar um modelo</strong></p><ol><li>Abra a capa do processo antes, para o eploc ler os dados usados nas variáveis.</li><li>Na tela de envio de e-mail, escolha o modelo no seletor. O texto entra no campo &quot;Mensagem&quot; e, se o modelo tiver assunto, ele substitui o do campo &quot;Assunto&quot;.</li><li>O modelo padrão é inserido sozinho ao abrir a tela, se o campo de mensagem estiver vazio.</li><li>Ao digitar &quot;@&quot; no assunto ou na mensagem, aparece a lista de variáveis. Escolha com as setas e Enter.</li></ol><p>Variáveis disponíveis:</p><table tabindex="0"><thead><tr><th>Variável</th><th>Conteúdo</th></tr></thead><tbody><tr><td><code>@numerodoprocesso@</code></td><td>Número do processo</td></tr><tr><td><code>@classe@</code></td><td>Classe do processo</td></tr><tr><td><code>@assuntoprincipal@</code></td><td>Assunto principal do processo</td></tr><tr><td><code>@orgaojulgador@</code></td><td>Órgão julgador</td></tr><tr><td><code>@nomedoautor@</code></td><td>Nome do primeiro autor (polo ativo)</td></tr><tr><td><code>@nomedosautoreslista@</code></td><td>Nomes de todos os autores, como &quot;A, B e C&quot;</td></tr><tr><td><code>@nomedoreu@</code></td><td>Nome do primeiro réu (polo passivo)</td></tr><tr><td><code>@nomedosreuslista@</code></td><td>Nomes de todos os réus, como &quot;A, B e C&quot;</td></tr><tr><td><code>@datadehoje@</code></td><td>Data de hoje (dd/mm/aaaa)</td></tr></tbody></table><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar. Os modelos são gerenciados em <strong>Gerenciar modelos de mensagem</strong>.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O campo de mensagem do eproc não aceita formatação (negrito, listas etc.). Os modelos são texto simples.</li><li>A tela de e-mail não traz os dados do processo. Eles são lidos da capa e guardados só neste computador, por até 24 horas, fora dos backups. Se a capa não tiver sido aberta, o eploc avisa quais variáveis ficaram sem dados.</li></ul>',16)]))}const g=e(t,[["render",r]]);export{u as __pageData,g as default};
